// ---- content/cong.js ----
// Тема «Сравнения по модулю. Теоремы Ферма, Эйлера, Вильсона» (8–10 класс + олимпиадный уровень).
// Продолжает тему «Делимость и остатки»: там основы сравнений, остатки квадратов, периоды степеней
// и формулировка малой теоремы Ферма. Здесь: деление сравнений и обратный элемент, доказательство
// теоремы Ферма, функция и теорема Эйлера, китайская теорема об остатках, теорема Вильсона, выбор модуля.
(function () {
  function fr(a, b) { return '<span class="fr"><span>' + a + '</span><span>' + b + '</span></span>'; }
  function md(m) { return ' (mod ' + m + ')'; }

  MM.addTopic({
    id: 'cong',
    sec: 'nt',
    title: 'Сравнения по модулю. Теоремы Ферма, Эйлера, Вильсона',
    blurb: `Главный инструмент олимпиадной теории чисел: как делить сравнения, считать огромные степени по любому модулю, решать системы сравнений и доказывать, что уравнение не имеет решений.`,

    lessons: [
      { id: 'cong-l1', title: 'Деление сравнений и обратный элемент', mins: 12, html: `
<p>Сравнения можно складывать, вычитать, умножать и возводить в степень — это было в теме «Делимость и остатки». С делением сложнее: <span class="m">6 ≡ 2${md(4)}</span>, но <span class="m">3 ≢ 1${md(4)}</span>. Разберёмся, когда делить можно.</p>
<div class="box"><div class="box-h">Правило деления</div><ul>
<li>Если <span class="m">ac ≡ bc${md('m')}</span> и НОД<span class="m">(c, m) = 1</span>, то <span class="m">a ≡ b${md('m')}</span>.</li>
<li>В общем случае <span class="m">ac ≡ bc${md('m')}</span> даёт <span class="m">a ≡ b (mod ${fr('m', 'd')})</span>, где <span class="m">d =</span> НОД<span class="m">(c, m)</span>.</li>
</ul></div>
<p>Почему: <span class="m">m</span> делит <span class="m">c(a − b)</span>, а с <span class="m">c</span> у него нет общих множителей, значит, <span class="m">m</span> делит <span class="m">a − b</span>.</p>
<h3>Обратный элемент</h3>
<p>Число <span class="m">x</span> называют <b>обратным</b> к <span class="m">a</span> по модулю <span class="m">m</span>, если <span class="m">ax ≡ 1${md('m')}</span>. Обратный существует ровно тогда, когда НОД<span class="m">(a, m) = 1</span>. Например, обратный к 3 по модулю 10 — это 7: <span class="m">3 · 7 = 21 ≡ 1</span>. Его ищут перебором небольших чисел или алгоритмом Евклида.</p>
<div class="ex"><div class="ex-h">Пример 1</div>
<p>Решите сравнение <span class="m">4x ≡ 7${md(9)}</span>.</p>
<p><b>Решение.</b> Обратный к 4 по модулю 9 — это 7: <span class="m">4 · 7 = 28 ≡ 1</span>. Умножим обе части на 7: <span class="m">x ≡ 49 ≡ 4${md(9)}</span>. Проверка: <span class="m">4 · 4 = 16 ≡ 7</span>.</p></div>
<h3>Когда НОД больше 1</h3>
<p>Сравнение <span class="m">ax ≡ b${md('m')}</span> при <span class="m">d =</span> НОД<span class="m">(a, m)</span> имеет решения тогда и только тогда, когда <span class="m">d <span class="dv">∣</span> b</span>, и тогда по модулю <span class="m">m</span> решений ровно <span class="m">d</span>.</p>
<div class="ex"><div class="ex-h">Пример 2</div>
<p>Решите сравнение <span class="m">4x ≡ 6${md(10)}</span>.</p>
<p><b>Решение.</b> НОД(4, 10) = 2 делит 6. Делим всё на 2: <span class="m">2x ≡ 3${md(5)}</span>, обратный к 2 по модулю 5 — это 3, поэтому <span class="m">x ≡ 9 ≡ 4${md(5)}</span>. По модулю 10 это два решения: <span class="m">x ≡ 4</span> и <span class="m">x ≡ 9</span>.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Уравнение в целых числах <span class="m">ax + by = c</span> — это сравнение <span class="m">ax ≡ c${md('b')}</span>. Найди <span class="m">x</span> по модулю <span class="m">b</span>, и все решения запишутся как <span class="m">x = x<sub>0</sub> + bt</span>.</p></div>` },

      { id: 'cong-l2', title: 'Малая теорема Ферма: доказательство и применения', mins: 14, html: `
<div class="box"><div class="box-h">Малая теорема Ферма</div>
<p>Если <span class="m">p</span> — простое и <span class="m">p ∤ a</span>, то <span class="m">a<sup>p−1</sup> ≡ 1${md('p')}</span>. Для любого целого <span class="m">a</span> верно <span class="m">a<sup>p</sup> ≡ a${md('p')}</span>.</p></div>
<h3>Доказательство</h3>
<p>Рассмотрим числа <span class="m">a, 2a, 3a, …, (p − 1)a</span>. Ни одно из них не делится на <span class="m">p</span>, и все они дают разные остатки: если <span class="m">ia ≡ ja</span>, то по правилу деления <span class="m">i ≡ j</span>. Значит, их остатки — это 1, 2, …, <span class="m">p − 1</span> в каком-то порядке. Например, при <span class="m">p = 7</span>, <span class="m">a = 3</span> остатки чисел 3, 6, 9, 12, 15, 18 — это 3, 6, 2, 5, 1, 4.</p>
<p>Перемножим: <span class="m">a<sup>p−1</sup> · (p − 1)! ≡ (p − 1)!${md('p')}</span>. Число <span class="m">(p − 1)!</span> взаимно просто с <span class="m">p</span>, на него можно сократить: <span class="m">a<sup>p−1</sup> ≡ 1</span>.</p>
<h3>Как применять</h3>
<ul>
<li><b>Показатель уменьшается по модулю p − 1.</b> Остаток <span class="m">3<sup>1000</sup></span> при делении на 13: <span class="m">1000 = 12 · 83 + 4</span>, поэтому <span class="m">3<sup>1000</sup> ≡ 3<sup>4</sup> = 81 ≡ 3${md(13)}</span>.</li>
<li><b>Делимость выражений.</b> <span class="m">n<sup>5</sup> − n</span> делится на 30, то есть на 2, 3 и 5. Возьмём любое из этих простых <span class="m">p</span>. Если <span class="m">p <span class="dv">∣</span> n</span>, всё ясно. Иначе <span class="m">n<sup>p−1</sup> ≡ 1</span>, а <span class="m">p − 1</span> (это 1, 2 или 4) делит 4, поэтому <span class="m">n<sup>4</sup> ≡ 1</span> и <span class="m">n<sup>5</sup> ≡ n${md('p')}</span>.</li>
<li><b>Степень p − 1 даёт только 0 или 1:</b> <span class="m">k<sup>p−1</sup> ≡ 1</span>, если <span class="m">p ∤ k</span>, и <span class="m">≡ 0</span>, если <span class="m">p <span class="dv">∣</span> k</span>.</li>
</ul>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Видишь огромный показатель и простой модуль — делим показатель на <span class="m">p − 1</span> с остатком. Видишь <span class="m">n<sup>k</sup> − n</span> — проверяем, для каких простых <span class="m">p</span> число <span class="m">p − 1</span> делит <span class="m">k − 1</span>: для них <span class="m">n<sup>k</sup> ≡ n${md('p')}</span>.</p></div>` },

      { id: 'cong-l3', title: 'Функция Эйлера и теорема Эйлера', mins: 14, html: `
<p><b>Функция Эйлера</b> <span class="m">φ(m)</span> — количество чисел от 1 до <span class="m">m</span>, взаимно простых с <span class="m">m</span>. Например, <span class="m">φ(10) = 4</span>: это 1, 3, 7, 9.</p>
<div class="box"><div class="box-h">Как считать</div><ul>
<li><span class="m">φ(p) = p − 1</span> для простого <span class="m">p</span>; <span class="m">φ(p<sup>k</sup>) = p<sup>k</sup> − p<sup>k−1</sup></span>: вычитаем числа, кратные <span class="m">p</span>.</li>
<li>Если <span class="m">m = p<sub>1</sub><sup>k<sub>1</sub></sup> … p<sub>s</sub><sup>k<sub>s</sub></sup></span>, то <span class="m">φ(m) = m(1 − ${fr('1', 'p<sub>1</sub>')}) … (1 − ${fr('1', 'p<sub>s</sub>')})</span>.</li>
</ul>
<p>Например, <span class="m">φ(36) = 36 · ${fr('1', '2')} · ${fr('2', '3')} = 12</span>.</p></div>
<div class="box"><div class="box-h">Теорема Эйлера</div>
<p>Если НОД<span class="m">(a, m) = 1</span>, то <span class="m">a<sup>φ(m)</sup> ≡ 1${md('m')}</span>.</p></div>
<p>Доказательство такое же, как у теоремы Ферма: если <span class="m">r<sub>1</sub>, …, r<sub>φ(m)</sub></span> — числа, взаимно простые с <span class="m">m</span>, то <span class="m">ar<sub>1</sub>, …, ar<sub>φ(m)</sub></span> дают те же остатки в другом порядке. Перемножаем и сокращаем.</p>
<div class="ex"><div class="ex-h">Пример 1</div>
<p>Найдите две последние цифры числа <span class="m">11<sup>123</sup></span>.</p>
<p><b>Решение.</b> <span class="m">φ(100) = 40</span>, а <span class="m">123 = 40 · 3 + 3</span>, поэтому <span class="m">11<sup>123</sup> ≡ 11<sup>3</sup> = 1331 ≡ 31${md(100)}</span>. Последние цифры — 31.</p></div>
<h3>Степенные башни</h3>
<div class="ex"><div class="ex-h">Пример 2</div>
<p>Найдите последнюю цифру числа <span class="m">3<sup>3<sup>3</sup></sup> = 3<sup>27</sup></span>.</p>
<p><b>Решение.</b> <span class="m">φ(10) = 4</span>, поэтому важен остаток показателя при делении на 4: <span class="m">27 ≡ 3${md(4)}</span>. Значит, <span class="m">3<sup>27</sup> ≡ 3<sup>3</sup> = 27 ≡ 7${md(10)}</span>.</p></div>
<p>Для башни из нескольких этажей спускаемся сверху вниз: показатель каждого этажа нужен по модулю <span class="m">φ</span> от модуля этажа ниже.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Сокращать показатель по модулю <span class="m">φ(m)</span> можно, только если основание взаимно просто с <span class="m">m</span>. Если нет — разложи модуль на взаимно простые множители (например, <span class="m">100 = 4 · 25</span>) и считай по каждому отдельно: как собрать ответ, расскажет следующий урок.</p></div>` },

      { id: 'cong-l4', title: 'Системы сравнений и китайская теорема', mins: 14, html: `
<div class="ex"><div class="ex-h">Пример 1</div>
<p>Найдите все <span class="m">x</span>, для которых <span class="m">x ≡ 2${md(3)}</span> и <span class="m">x ≡ 3${md(4)}</span>.</p>
<p><b>Решение.</b> Из второго сравнения <span class="m">x = 4k + 3</span>. Подставим в первое: <span class="m">4k + 3 ≡ k ≡ 2${md(3)}</span>, то есть <span class="m">k = 3j + 2</span> и <span class="m">x = 12j + 11</span>. Ответ: <span class="m">x ≡ 11${md(12)}</span>.</p></div>
<div class="box"><div class="box-h">Китайская теорема об остатках</div>
<p>Если модули <span class="m">m<sub>1</sub>, …, m<sub>k</sub></span> попарно взаимно просты, то система <span class="m">x ≡ a<sub>i</sub>${md('m<sub>i</sub>')}</span> имеет решение, и оно единственно по модулю <span class="m">m<sub>1</sub>m<sub>2</sub> … m<sub>k</sub></span>.</p></div>
<p>Почему: остатки по модулю <span class="m">M = m<sub>1</sub> … m<sub>k</sub></span> дают разные наборы остатков по модулям <span class="m">m<sub>i</sub></span> (разность двух чисел с одинаковым набором делится на все <span class="m">m<sub>i</sub></span>, а значит, и на <span class="m">M</span>). Остатков по модулю <span class="m">M</span> столько же, сколько наборов, поэтому каждый набор встречается ровно один раз.</p>
<h3>Модули с общими делителями</h3>
<p>Тогда система может не иметь решений. <span class="m">x ≡ 1${md(6)}</span> и <span class="m">x ≡ 2${md(4)}</span> несовместны: первое даёт нечётное <span class="m">x</span>, второе — чётное. А <span class="m">x ≡ 1${md(6)}</span> и <span class="m">x ≡ 3${md(4)}</span> совместны: <span class="m">x ≡ 7${md(12)}</span>. Правило: остатки должны совпадать по модулю НОД модулей.</p>
<h3>Считаем по составному модулю по частям</h3>
<div class="ex"><div class="ex-h">Пример 2</div>
<p>Найдите остаток от деления <span class="m">2<sup>30</sup></span> на 24.</p>
<p><b>Решение.</b> Теорема Эйлера не годится: 2 и 24 не взаимно просты. Но <span class="m">24 = 8 · 3</span>. По модулю 8: <span class="m">2<sup>30</sup> ≡ 0</span>. По модулю 3: <span class="m">2<sup>30</sup> = 4<sup>15</sup> ≡ 1</span>. Число от 0 до 23, делящееся на 8 и дающее остаток 1 при делении на 3, — это 16. Ответ: 16.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Китайская теорема позволяет думать о каждом простом множителе модуля отдельно. Число решений сравнения по модулю <span class="m">m = m<sub>1</sub>m<sub>2</sub></span> (взаимно простые множители) равно произведению чисел решений по модулям <span class="m">m<sub>1</sub></span> и <span class="m">m<sub>2</sub></span>.</p></div>` },

      { id: 'cong-l5', title: 'Теорема Вильсона', mins: 12, html: `
<div class="box"><div class="box-h">Теорема Вильсона</div>
<p>Если <span class="m">p</span> — простое число, то <span class="m">(p − 1)! ≡ −1${md('p')}</span>.</p></div>
<p>Проверка: <span class="m">6! = 720 = 721 − 1</span>, а <span class="m">721 = 7 · 103</span>.</p>
<h3>Доказательство</h3>
<p>При <span class="m">p = 2</span> и <span class="m">p = 3</span> проверяется сразу. Пусть <span class="m">p ≥ 5</span>. Каждое число <span class="m">a</span> от 1 до <span class="m">p − 1</span> имеет обратный <span class="m">a<sup>−1</sup></span> среди этих же чисел. Число совпадает со своим обратным, только если <span class="m">a<sup>2</sup> ≡ 1</span>, то есть <span class="m">p <span class="dv">∣</span> (a − 1)(a + 1)</span>: это <span class="m">a = 1</span> и <span class="m">a = p − 1</span>. Остальные числа <span class="m">2, 3, …, p − 2</span> разбиваются на пары «число и обратное», и произведение каждой пары <span class="m">≡ 1</span>. Поэтому <span class="m">(p − 1)! ≡ 1 · (p − 1) ≡ −1${md('p')}</span>.</p>
<h3>Обратное тоже верно</h3>
<p>Если <span class="m">n > 1</span> составное, то у него есть делитель <span class="m">d</span>, <span class="m">1 < d < n</span>. Он входит в произведение <span class="m">(n − 1)!</span> и поэтому не делит <span class="m">(n − 1)! + 1</span>. Значит, <span class="m">n <span class="dv">∣</span> (n − 1)! + 1</span> ровно для простых <span class="m">n</span>.</p>
<h3>Следствия</h3>
<ul>
<li><span class="m">(p − 2)! ≡ 1${md('p')}</span>: делим <span class="m">(p − 1)! ≡ −1</span> на <span class="m">p − 1 ≡ −1</span>.</li>
<li>Множители большой половины факториала можно заменить отрицательными: <span class="m">p − k ≡ −k${md('p')}</span>. Например, <span class="m">12 · 11 · 10 ≡ (−1)(−2)(−3) = −6${md(13)}</span>.</li>
</ul>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Факториал по простому модулю почти всегда сводится к теореме Вильсона: допиши недостающие множители до <span class="m">(p − 1)!</span>, замени их на маленькие отрицательные и раздели.</p></div>` },

      { id: 'cong-l6', title: 'Олимпиадные приёмы: выбор модуля', mins: 16, html: `
<p>Чтобы доказать, что уравнение не имеет решений в целых числах, достаточно найти модуль, по которому левая и правая части не могут быть равны. Искусство — выбрать удачный модуль: такой, по которому степени принимают мало значений.</p>
<div class="box"><div class="box-h">Таблица</div><ul>
<li>Квадраты: по модулю 4 — 0, 1; по модулю 8 — 0, 1, 4; по модулю 3 — 0, 1.</li>
<li>Кубы: по модулю 7 — 0, 1, 6; по модулю 9 — 0, 1, 8.</li>
<li>Четвёртые степени: по модулю 16 — 0, 1; по модулю 5 — 0, 1.</li>
</ul></div>
<p>Откуда это берётся: по теореме Ферма <span class="m">x<sup>p−1</sup></span> по простому модулю <span class="m">p</span> даёт только 0 или 1. Если <span class="m">k <span class="dv">∣</span> p − 1</span>, то <span class="m">k</span>-е степени принимают по модулю <span class="m">p</span> мало значений: например, для кубов подходит <span class="m">p = 7</span> (3 делит 6).</p>
<div class="ex"><div class="ex-h">Пример 1</div>
<p>Докажите, что уравнение <span class="m">x<sup>3</sup> + y<sup>3</sup> + z<sup>3</sup> = 2030</span> не имеет решений в целых числах.</p>
<p><b>Решение.</b> Кубы по модулю 9 дают 0, 1 или 8, поэтому сумма трёх кубов даёт любой остаток, кроме 4 и 5. А <span class="m">2030 ≡ 5${md(9)}</span>.</p></div>
<div class="ex"><div class="ex-h">Пример 2</div>
<p>Докажите, что уравнение <span class="m">x<sup>4</sup> + y<sup>4</sup> = 2026</span> не имеет решений в целых числах.</p>
<p><b>Решение.</b> Четвёртые степени по модулю 16 дают 0 или 1, сумма двух — 0, 1 или 2. А <span class="m">2026 ≡ 10${md(16)}</span>.</p></div>
<h3>Когда −1 не бывает квадратом</h3>
<p>Пусть <span class="m">p = 4k + 3</span> — простое. Тогда сравнение <span class="m">x<sup>2</sup> ≡ −1${md('p')}</span> не имеет решений. Действительно, иначе <span class="m">p ∤ x</span> и по теореме Ферма <span class="m">1 ≡ x<sup>p−1</sup> = (x<sup>2</sup>)<sup>2k+1</sup> ≡ (−1)<sup>2k+1</sup> = −1</span> — противоречие. Например, <span class="m">n<sup>2</sup> + 1</span> никогда не делится на 3, 7, 11, 19, 23, …</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Для <span class="m">k</span>-х степеней пробуй модули <span class="m">p</span>, у которых <span class="m">k <span class="dv">∣</span> p − 1</span>: для квадратов — 3, 5, 8; для кубов — 7, 9; для четвёртых степеней — 5, 16; для пятых — 11. Если не получилось с одним модулем, попробуй другой: у разных уравнений «свой» модуль.</p></div>` }
    ],

    problems: [
      // ── Уровень 1 · База ──
      { id: 'cong-01', lvl: 1, r: 800, type: 'num', q: `Решите сравнение 3x ≡ 1${md(7)}. В ответ запишите наименьшее натуральное решение.`, a: ['5'],
        hints: [`Подбери x от 1 до 6, для которого 3x даёт остаток 1 при делении на 7.`],
        sol: `3 · 5 = 15 = 14 + 1 ≡ 1${md(7)}. Это обратный к 3 по модулю 7, и все решения — x ≡ 5${md(7)}.` },
      { id: 'cong-02', lvl: 1, r: 830, type: 'num', q: `Найдите φ(12) — количество чисел от 1 до 12, взаимно простых с 12.`, a: ['4'],
        hints: [`Выпиши числа от 1 до 12, у которых нет общих делителей с 12, кроме 1.`],
        sol: `Подходят 1, 5, 7, 11 — четыре числа. По формуле: φ(12) = 12 · ${fr('1', '2')} · ${fr('2', '3')} = 4.` },
      { id: 'cong-03', lvl: 1, r: 860, type: 'num', q: `Число 2027 — простое. Найдите остаток от деления 2<sup>2026</sup> на 2027.`, a: ['1'],
        hints: [`Малая теорема Ферма для p = 2027.`],
        sol: `2027 — простое и не делит 2, поэтому по теореме Ферма 2<sup>2026</sup> ≡ 1${md(2027)}.` },
      { id: 'cong-04', lvl: 1, r: 890, type: 'choice', q: `При каком a сравнение 6x ≡ a${md(9)} имеет решение?`, opts: ['a = 1', 'a = 2', 'a = 3', 'a = 4'], a: 2,
        hints: [`Сравнение ax ≡ b${md('m')} решается, когда НОД(a, m) делит b.`],
        sol: `НОД(6, 9) = 3, поэтому решения есть только при a, кратном 3. Подходит a = 3: например, 6 · 2 = 12 ≡ 3${md(9)}.` },
      { id: 'cong-05', lvl: 1, r: 920, type: 'num', q: `Найдите наименьшее натуральное число, которое при делении на 3 даёт остаток 2, а при делении на 5 — остаток 3.`, a: ['8'],
        hints: [`Выпиши числа с остатком 3 при делении на 5: 3, 8, 13, … — и проверь остаток при делении на 3.`],
        sol: `Из чисел 3, 8, 13, … первое с остатком 2 при делении на 3 — это 8. Все такие числа: 8, 23, 38, … (шаг 15).` },
      { id: 'cong-06', lvl: 1, r: 960, type: 'num', q: `Найдите φ(100).`, a: ['40'],
        hints: [`100 = 2<sup>2</sup> · 5<sup>2</sup>. Используй формулу φ(m) = m(1 − 1/p<sub>1</sub>)…(1 − 1/p<sub>s</sub>).`],
        sol: `φ(100) = 100 · ${fr('1', '2')} · ${fr('4', '5')} = 40.` },
      { id: 'cong-07', lvl: 1, r: 1000, type: 'num', q: `Найдите остаток от деления 10! на 11.`, a: ['10'],
        hints: [`Теорема Вильсона для p = 11.`],
        sol: `По теореме Вильсона 10! ≡ −1 ≡ 10${md(11)}. Проверка: 10! = 3628800 = 11 · 329891 − 1.` },
      { id: 'cong-08', lvl: 1, r: 1040, type: 'num', q: `Найдите остаток от деления 3<sup>40</sup> на 100.`, a: ['1'],
        hints: [`φ(100) = 40, а 3 и 100 взаимно просты.`],
        sol: `По теореме Эйлера 3<sup>φ(100)</sup> = 3<sup>40</sup> ≡ 1${md(100)}.` },

      // ── Уровень 2 · Районный этап ──
      { id: 'cong-09', lvl: 2, r: 1070, type: 'num', q: `Решите сравнение 7x ≡ 3${md(11)}. В ответ запишите наименьшее натуральное решение.`, a: ['2'],
        hints: [`Найди обратный к 7 по модулю 11.`, `7 · 8 = 56 ≡ 1${md(11)}.`],
        sol: `Обратный к 7 по модулю 11 — это 8. Умножаем: x ≡ 3 · 8 = 24 ≡ 2${md(11)}. Проверка: 7 · 2 = 14 ≡ 3.` },
      { id: 'cong-10', lvl: 2, r: 1100, type: 'num', q: `Сколько решений имеет сравнение 6x ≡ 9${md(15)} среди чисел 0, 1, 2, …, 14?`, a: ['3'],
        hints: [`НОД(6, 15) = 3 делит 9. Сократи всё на 3.`],
        sol: `Делим на 3: 2x ≡ 3${md(5)}, x ≡ 4${md(5)}. По модулю 15 это x = 4, 9, 14 — три решения (их число равно НОД(6, 15) = 3).` },
      { id: 'cong-11', lvl: 2, r: 1130, type: 'num', q: `Найдите остаток от деления 2026<sup>2026</sup> на 7.`, a: ['4'],
        hints: [`2026 ≡ 3${md(7)}. Показатель уменьши по модулю 6.`],
        sol: `2026 = 7 · 289 + 3, так что 2026<sup>2026</sup> ≡ 3<sup>2026</sup>${md(7)}. По теореме Ферма 3<sup>6</sup> ≡ 1, а 2026 = 6 · 337 + 4. Значит, ответ — остаток 3<sup>4</sup> = 81, то есть 4.` },
      { id: 'cong-12', lvl: 2, r: 1160, type: 'num', q: `Найдите φ(2026).`, a: ['1012'],
        hints: [`2026 = 2 · 1013, и 1013 — простое.`],
        sol: `1013 не делится ни на одно простое до 31 (а 32<sup>2</sup> > 1013), значит, оно простое. φ(2026) = φ(2) · φ(1013) = 1 · 1012 = 1012.` },
      { id: 'cong-13', lvl: 2, r: 1190, type: 'num', q: `Найдите остаток от деления числа 1<sup>6</sup> + 2<sup>6</sup> + 3<sup>6</sup> + … + 100<sup>6</sup> на 7.`, a: ['2'],
        hints: [`По теореме Ферма k<sup>6</sup> ≡ 1${md(7)}, если 7 ∤ k.`, `Сколько чисел от 1 до 100 не делятся на 7?`],
        sol: `Слагаемое k<sup>6</sup> даёт остаток 1, если k не делится на 7, и 0 иначе. Чисел от 1 до 100, не делящихся на 7, ровно 100 − 14 = 86, а 86 = 7 · 12 + 2. Ответ: 2.` },
      { id: 'cong-14', lvl: 2, r: 1220, type: 'num', q: `Число n при делении на 4 даёт остаток 1, а при делении на 5 — остаток 3. Какой остаток даёт n при делении на 20?`, a: ['13'],
        hints: [`Числа с остатком 3 при делении на 5: 3, 8, 13, 18. Какое из них даёт остаток 1 при делении на 4?`],
        sol: `Среди остатков по модулю 20, равных 3 по модулю 5, — 3, 8, 13, 18 — остаток 1 по модулю 4 даёт только 13. По китайской теореме ответ единственен: 13.` },
      { id: 'cong-15', lvl: 2, r: 1250, type: 'choice', q: `Какое из чисел делится на 7 при любом целом n?`, opts: ['n<sup>7</sup> − n', 'n<sup>6</sup> − n', 'n<sup>7</sup> + n', 'n<sup>6</sup> + 1'], a: 0,
        hints: [`Малая теорема Ферма в форме a<sup>p</sup> ≡ a${md('p')}.`],
        sol: `По теореме Ферма n<sup>7</sup> ≡ n${md(7)}, поэтому n<sup>7</sup> − n делится на 7 всегда. Остальные не подходят: при n = 2 они равны 62, 130 и 65, и ни одно не делится на 7.` },
      { id: 'cong-16', lvl: 2, r: 1280, type: 'num', q: `Найдите остаток от деления 2<sup>100</sup> + 3<sup>100</sup> + 4<sup>100</sup> на 5.`, a: ['3'],
        hints: [`По теореме Ферма a<sup>4</sup> ≡ 1${md(5)}, если 5 ∤ a.`],
        sol: `100 делится на 4, поэтому каждое слагаемое ≡ 1${md(5)}. Сумма ≡ 3.` },
      { id: 'cong-17', lvl: 2, r: 1310, type: 'num', q: `Найдите число x от 1 до 16, обратное к 5 по модулю 17, то есть такое, что 5x ≡ 1${md(17)}.`, a: ['7'],
        hints: [`Ищи число, кратное 5, которое на 1 больше числа, кратного 17: 18, 35, 52, …`],
        sol: `35 = 2 · 17 + 1 и 35 = 5 · 7. Значит, 5 · 7 ≡ 1${md(17)}, x = 7.` },
      { id: 'cong-18', lvl: 2, r: 1340, type: 'num', q: `Найдите наименьшее натуральное x, при котором 2026x − 1 делится на 11.`, a: ['6'],
        hints: [`2026 ≡ 2${md(11)}.`],
        sol: `2026 = 11 · 184 + 2, поэтому нужно 2x ≡ 1${md(11)}. Обратный к 2 по модулю 11 — это 6. Проверка: 2026 · 6 − 1 = 12155 = 11 · 1105.` },

      // ── Уровень 3 · Полуфинал ──
      { id: 'cong-19', lvl: 3, r: 1370, type: 'num', q: `Найдите остаток от деления 13<sup>2026</sup> на 100.`, a: ['9'],
        hints: [`φ(100) = 40, а 2026 ≡ 26${md(40)}.`, `Возводи 13 в квадрат несколько раз: 13<sup>2</sup>, 13<sup>4</sup>, 13<sup>8</sup>, 13<sup>16</sup> по модулю 100.`],
        sol: `По теореме Эйлера 13<sup>40</sup> ≡ 1${md(100)}, и 2026 = 40 · 50 + 26, так что нужно 13<sup>26</sup>. По модулю 100: 13<sup>2</sup> ≡ 69, 13<sup>4</sup> ≡ 69<sup>2</sup> = 4761 ≡ 61, 13<sup>8</sup> ≡ 61<sup>2</sup> = 3721 ≡ 21, 13<sup>16</sup> ≡ 21<sup>2</sup> = 441 ≡ 41. Тогда 13<sup>26</sup> = 13<sup>16</sup> · 13<sup>8</sup> · 13<sup>2</sup> ≡ 41 · 21 · 69 ≡ 61 · 69 = 4209 ≡ 9. Ответ: 9 (число оканчивается на 09).` },
      { id: 'cong-20', lvl: 3, r: 1400, type: 'num', q: `Найдите остаток от деления 14! на 17.`, a: ['8'],
        hints: [`По теореме Вильсона 16! ≡ −1${md(17)}.`, `16! = 14! · 15 · 16, а 15 ≡ −2, 16 ≡ −1.`],
        sol: `16! = 14! · 15 · 16 ≡ 14! · (−2)(−1) = 2 · 14!${md(17)}. По теореме Вильсона 2 · 14! ≡ −1 ≡ 16, откуда 14! ≡ 8${md(17)}.` },
      { id: 'cong-21', lvl: 3, r: 1430, type: 'num', q: `Найдите последнюю цифру числа 7<sup>7<sup>7</sup></sup>.`, a: ['3'],
        hints: [`Последние цифры степеней 7 повторяются с периодом 4. Нужен остаток показателя 7<sup>7</sup> при делении на 4.`, `7 ≡ −1${md(4)}.`],
        sol: `Последние цифры степеней 7 — 7, 9, 3, 1 — повторяются с периодом 4 (φ(10) = 4). Показатель 7<sup>7</sup> ≡ (−1)<sup>7</sup> = −1 ≡ 3${md(4)}. Значит, последняя цифра такая же, как у 7<sup>3</sup> = 343, — это 3.` },
      { id: 'cong-22', lvl: 3, r: 1460, type: 'num', q: `Найдите наименьшее натуральное число, которое при делении на 3 даёт остаток 2, при делении на 5 — остаток 3, а при делении на 7 — остаток 2.`, a: ['23'],
        hints: [`Сначала два сравнения: x ≡ 2${md(3)} и x ≡ 2${md(7)} — это x ≡ 2${md(21)}.`, `Числа 2, 23, 44, … — какое даёт остаток 3 при делении на 5?`],
        sol: `Первое и третье условия равносильны x ≡ 2${md(21)}: числа 2, 23, 44, … Остаток 3 при делении на 5 даёт 23. Это старинная задача китайского математика Сунь-цзы — отсюда и название теоремы.` },
      { id: 'cong-23', lvl: 3, r: 1490, type: 'num', q: `Сколько чисел от 1 до 1000 при делении на 4 дают остаток 3, а при делении на 6 — остаток 5?`, a: ['83'],
        hints: [`Остаток 3 при делении на 4 — это −1${md(4)}, остаток 5 при делении на 6 — это −1${md(6)}.`],
        sol: `Условия означают, что x + 1 делится на 4 и на 6, то есть на 12: x = 12k − 1. При k = 1, …, 83 получаем числа от 11 до 995, а при k = 84 уже 1007. Ответ: 83.` },
      { id: 'cong-24', lvl: 3, r: 1520, type: 'num', q: `Сколько чисел x среди 0, 1, 2, …, 23 удовлетворяют сравнению x<sup>2</sup> ≡ 1${md(24)}?`, a: ['8'],
        hints: [`24 = 8 · 3. Реши сравнение по модулю 8 и по модулю 3 отдельно.`, `По модулю 8 квадрат нечётного числа всегда 1, по модулю 3 нужно x ≢ 0.`],
        sol: `По модулю 8: x<sup>2</sup> ≡ 1 для всех нечётных x — 4 остатка. По модулю 3: x ≡ 1 или 2 — 2 остатка. По китайской теореме решений 4 · 2 = 8: это все числа, взаимно простые с 24 (1, 5, 7, 11, 13, 17, 19, 23).` },
      { id: 'cong-25', lvl: 3, r: 1550, type: 'num', q: `Сколько существует чисел x от 1 до 210, для которых x<sup>2</sup> − x делится на 210?`, a: ['16'],
        hints: [`210 = 2 · 3 · 5 · 7. По простому модулю p условие x(x − 1) ≡ 0 даёт x ≡ 0 или x ≡ 1.`],
        sol: `По каждому из модулей 2, 3, 5, 7 есть ровно 2 решения: x ≡ 0 или 1 (простое число делит произведение, только если делит множитель). По китайской теореме число решений по модулю 210 равно 2<sup>4</sup> = 16.` },
      { id: 'cong-26', lvl: 3, r: 1580, type: 'num', q: `Найдите остаток от деления 2<sup>2026</sup> на 100.`, a: ['64'],
        hints: [`Теорема Эйлера по модулю 100 не работает: 2 и 100 не взаимно просты. Раздели модуль: 100 = 4 · 25.`, `По модулю 25: φ(25) = 20 и 2026 ≡ 6${md(20)}.`],
        sol: `По модулю 4: 2<sup>2026</sup> ≡ 0. По модулю 25: 2<sup>20</sup> ≡ 1, 2026 = 20 · 101 + 6, поэтому 2<sup>2026</sup> ≡ 2<sup>6</sup> = 64 ≡ 14. Нужно число от 0 до 99, делящееся на 4 и дающее остаток 14 при делении на 25: из 14, 39, 64, 89 подходит 64.` },
      { id: 'cong-27', lvl: 3, r: 1610, type: 'choice', q: `По какому модулю сразу видно, что уравнение x<sup>3</sup> + y<sup>3</sup> = 2026 не имеет решений в целых числах?`, opts: ['по модулю 4', 'по модулю 9', 'по модулю 7', 'по модулю 5'], a: 2,
        hints: [`Для кубов удобны модули 7 и 9. Проверь оба.`, `Кубы по модулю 7 — 0, 1, 6. Какие остатки дают суммы двух таких чисел?`],
        sol: `Кубы по модулю 7 дают 0, 1, 6, а их попарные суммы — 0, 1, 2, 5, 6. Но 2026 = 7 · 289 + 3, остаток 3 не получается. По модулю 9 суммы кубов дают 0, 1, 2, 7, 8, а 2026 ≡ 1 — противоречия нет. По модулям 4 и 5 противоречия тоже нет (2026 ≡ 2 = 1 + 1 по модулю 4; по модулю 5 кубы принимают все остатки).` },
      { id: 'cong-28', lvl: 3, r: 1640, type: 'num', q: `Число 101 — простое. Найдите остаток от деления (50!)<sup>2</sup> на 101.`, a: ['100'],
        hints: [`100! = 50! · (51 · 52 · … · 100). Замени каждый множитель второй скобки по модулю 101 на отрицательный.`, `51 · 52 · … · 100 ≡ (−50)(−49)…(−1) = 50!${md(101)}.`],
        sol: `Так как 101 − k ≡ −k, произведение 51 · 52 · … · 100 ≡ (−50)(−49)…(−1) = (−1)<sup>50</sup> · 50! = 50!${md(101)}. Значит, 100! ≡ (50!)<sup>2</sup>, а по теореме Вильсона 100! ≡ −1 ≡ 100${md(101)}.` },

      // ── Уровень 4 · Финал ──
      { id: 'cong-29', lvl: 4, r: 1680, type: 'num', q: `Найдите наименьшее натуральное число, которое при делении на 2, 3, 4, 5 и 6 даёт остатки 1, 2, 3, 4 и 5 соответственно, а на 7 делится нацело.`, a: ['119'],
        hints: [`Остатки на 1 меньше делителей: x + 1 делится на 2, 3, 4, 5, 6.`, `x = 60k − 1. Найди k, при котором 7 <span class="dv">∣</span> x.`],
        sol: `x + 1 делится на НОК(2, 3, 4, 5, 6) = 60, то есть x = 60k − 1. Нужно 60k ≡ 1${md(7)}, то есть 4k ≡ 1, k ≡ 2${md(7)}. Наименьшее: k = 2, x = 119 = 7 · 17.` },
      { id: 'cong-30', lvl: 4, r: 1720, type: 'proof', q: `Пусть p > 2 — простое число. Докажите, что 1<sup>2</sup> · 3<sup>2</sup> · 5<sup>2</sup> · … · (p − 2)<sup>2</sup> ≡ (−1)<sup>(p+1)/2</sup>${md('p')}.`,
        hints: [`Разбей (p − 1)! на произведение нечётных и чётных множителей.`, `Чётные множители 2, 4, …, p − 1 по модулю p равны −(p − 2), −(p − 4), …, −1.`, `Примени теорему Вильсона.`],
        sol: `Пусть A = 1 · 3 · 5 · … · (p − 2). Чётные числа 2, 4, …, p − 1 по модулю p равны −(p − 2), −(p − 4), …, −1, то есть их произведение ≡ (−1)<sup>(p−1)/2</sup> · A (их ровно ${fr('p − 1', '2')}). Значит, (p − 1)! ≡ A · (−1)<sup>(p−1)/2</sup> · A. По теореме Вильсона (p − 1)! ≡ −1, поэтому A<sup>2</sup> ≡ −(−1)<sup>(p−1)/2</sup> = (−1)<sup>(p+1)/2</sup>.`,
        rubric: [[2, `(p − 1)! разбито на нечётные и чётные множители`], [3, `Чётные множители выражены через нечётные: произведение ≡ (−1)<sup>(p−1)/2</sup> · A`], [2, `Применена теорема Вильсона, вывод`]] },
      { id: 'cong-31', lvl: 4, r: 1760, type: 'num', q: `Найдите остаток от деления числа 3<sup>3<sup>3<sup>3</sup></sup></sup> = 3<sup>3<sup>27</sup></sup> на 100.`, a: ['87'],
        hints: [`φ(100) = 40, поэтому нужен остаток показателя 3<sup>27</sup> при делении на 40.`, `3<sup>4</sup> = 81 ≡ 1${md(40)}.`],
        sol: `Нужно 3<sup>27</sup> по модулю 40: 3<sup>4</sup> ≡ 1${md(40)}, поэтому 3<sup>27</sup> = (3<sup>4</sup>)<sup>6</sup> · 3<sup>3</sup> ≡ 27. Значит, 3<sup>3<sup>27</sup></sup> ≡ 3<sup>27</sup>${md(100)}. Дальше 3<sup>20</sup> ≡ 1${md(100)} (например, 3<sup>10</sup> = 59049 ≡ 49 и 49<sup>2</sup> = 2401 ≡ 1), так что 3<sup>27</sup> ≡ 3<sup>7</sup> = 2187 ≡ 87.` },
      { id: 'cong-32', lvl: 4, r: 1800, type: 'proof', q: `Докажите, что число 2<sup>70</sup> + 3<sup>70</sup> делится на 13.`,
        hints: [`Найди периоды степеней 2 и 3 по модулю 13.`, `3<sup>3</sup> = 27 ≡ 1${md(13)}, а 2<sup>6</sup> = 64 ≡ −1${md(13)}.`],
        sol: `3<sup>3</sup> = 27 ≡ 1${md(13)}, а 70 = 3 · 23 + 1, поэтому 3<sup>70</sup> ≡ 3. Далее 2<sup>6</sup> = 64 ≡ −1, значит, 2<sup>12</sup> ≡ 1 и 2<sup>70</sup> = 2<sup>60</sup> · 2<sup>10</sup> ≡ 2<sup>10</sup> = 1024 = 13 · 78 + 10 ≡ 10. Сумма ≡ 10 + 3 = 13 ≡ 0${md(13)}.`,
        rubric: [[3, `Найден остаток 3<sup>70</sup> ≡ 3`], [3, `Найден остаток 2<sup>70</sup> ≡ 10`], [1, `Вывод`]] },
      { id: 'cong-33', lvl: 4, r: 1840, type: 'num', q: `Найдите остаток от деления 2<sup>1000</sup> на 1001.`, a: ['562'],
        hints: [`1001 = 7 · 11 · 13. Найди остатки по каждому из этих модулей теоремой Ферма.`, `2<sup>1000</sup> ≡ 2${md(7)}, ≡ 1${md(11)}, ≡ 3${md(13)}. Собери ответ по китайской теореме.`],
        sol: `По теореме Ферма: по модулю 7 показатель важен по модулю 6, 1000 ≡ 4, 2<sup>4</sup> = 16 ≡ 2; по модулю 11 — по модулю 10, 1000 ≡ 0, остаток 1; по модулю 13 — по модулю 12, 1000 ≡ 4, 2<sup>4</sup> = 16 ≡ 3. Ищем x: x ≡ 1${md(11)} и x ≡ 3${md(13)} дают x ≡ 133${md(143)}; затем 133 + 143j ≡ 2${md(7)}, то есть 3j ≡ 2, j ≡ 3. Ответ: 133 + 429 = 562.` },
      { id: 'cong-34', lvl: 4, r: 1880, type: 'proof', q: `Простое число p даёт остаток 3 при делении на 4, и p делит a<sup>2</sup> + b<sup>2</sup> (a, b — целые). Докажите, что p делит и a, и b.`,
        hints: [`Пусть p ∤ b. Тогда у b есть обратный по модулю p.`, `Тогда (ab<sup>−1</sup>)<sup>2</sup> ≡ −1${md('p')}. Почему это невозможно?`],
        sol: `Предположим, p ∤ b. Тогда существует обратный c к b по модулю p, и из a<sup>2</sup> ≡ −b<sup>2</sup> получаем (ac)<sup>2</sup> ≡ −1${md('p')}. Но при p = 4k + 3 сравнение x<sup>2</sup> ≡ −1 не имеет решений: иначе p ∤ x и по теореме Ферма 1 ≡ x<sup>p−1</sup> = (x<sup>2</sup>)<sup>2k+1</sup> ≡ −1. Значит, p <span class="dv">∣</span> b, тогда p <span class="dv">∣</span> a<sup>2</sup>, и так как p простое, p <span class="dv">∣</span> a.`,
        rubric: [[2, `Предположение p ∤ b и переход к x<sup>2</sup> ≡ −1 через обратный элемент`], [4, `Доказано, что x<sup>2</sup> ≡ −1${md('p')} невозможно при p = 4k + 3`], [1, `Вывод p <span class="dv">∣</span> a и p <span class="dv">∣</span> b`]] },
      { id: 'cong-35', lvl: 4, r: 1920, type: 'num', q: `Найдите наименьшее натуральное n, для которого n делится на 9, n + 1 — на 25, а n + 2 — на 4.`, a: ['774'],
        hints: [`Это система n ≡ 0${md(9)}, n ≡ 24${md(25)}, n ≡ 2${md(4)}.`, `Сначала собери модуль 100: n ≡ 24${md(25)} и n ≡ 2${md(4)}.`],
        sol: `Из n ≡ 24${md(25)} и n ≡ 2${md(4)}: среди 24, 49, 74, 99 подходит 74, то есть n ≡ 74${md(100)}. Тогда n = 74 + 100k ≡ 2 + k${md(9)}, нужно k ≡ 7. Наименьшее n = 774: 774 = 9 · 86, 775 = 25 · 31, 776 = 4 · 194.` },
      { id: 'cong-36', lvl: 4, r: 1950, type: 'proof', q: `Докажите, что при любом целом n число n<sup>13</sup> − n делится на 2730.`,
        hints: [`2730 = 2 · 3 · 5 · 7 · 13.`, `Для каждого из этих простых p число p − 1 делит 12.`],
        sol: `2730 = 2 · 3 · 5 · 7 · 13 — произведение различных простых, поэтому достаточно доказать делимость на каждое из них. Для p = 2, 3, 5, 7, 13 число p − 1 (это 1, 2, 4, 6, 12) делит 12. Если p <span class="dv">∣</span> n, то p <span class="dv">∣</span> n<sup>13</sup> − n очевидно. Иначе по теореме Ферма n<sup>p−1</sup> ≡ 1, поэтому n<sup>12</sup> = (n<sup>p−1</sup>)<sup>12/(p−1)</sup> ≡ 1 и n<sup>13</sup> ≡ n${md('p')}.`,
        rubric: [[2, `Разложение 2730 на простые и сведение к каждому простому`], [3, `Для каждого p: p − 1 делит 12, применена теорема Ферма`], [2, `Разобран случай p <span class="dv">∣</span> n, вывод`]] },

      // ── Уровень 5 · Международный ──
      { id: 'cong-37', lvl: 5, r: 2060, type: 'proof', q: `Целые числа a и b таковы, что a<sup>2</sup> + b<sup>2</sup> делится на 21. Докажите, что a<sup>2</sup> + b<sup>2</sup> делится на 441.`,
        hints: [`21 = 3 · 7, и оба простых дают остаток 3 при делении на 4.`, `Если простое p = 4k + 3 делит a<sup>2</sup> + b<sup>2</sup>, то p делит и a, и b (задача 34).`],
        sol: `3 и 7 — простые вида 4k + 3, и каждое делит a<sup>2</sup> + b<sup>2</sup>. По утверждению задачи 34 (если p = 4k + 3 делит a<sup>2</sup> + b<sup>2</sup>, то p <span class="dv">∣</span> a и p <span class="dv">∣</span> b; доказательство: иначе (ab<sup>−1</sup>)<sup>2</sup> ≡ −1${md('p')}, что невозможно по теореме Ферма) получаем 3 <span class="dv">∣</span> a, 3 <span class="dv">∣</span> b, 7 <span class="dv">∣</span> a, 7 <span class="dv">∣</span> b. Значит, 21 <span class="dv">∣</span> a и 21 <span class="dv">∣</span> b, и a<sup>2</sup> + b<sup>2</sup> делится на 21<sup>2</sup> = 441.`,
        rubric: [[2, `Замечено, что 3 и 7 — простые вида 4k + 3`], [3, `Обосновано (или сослано с доказательством), что тогда каждое делит a и b`], [2, `Вывод 21 <span class="dv">∣</span> a, 21 <span class="dv">∣</span> b и делимость на 441`]] },
      { id: 'cong-38', lvl: 5, r: 2150, type: 'proof', q: `Натуральное число n взаимно просто с 10. Докажите, что существует число вида 11…1 (записанное одними единицами), которое делится на n.`,
        hints: [`Число из k единиц равно (10<sup>k</sup> − 1)/9.`, `Нужно, чтобы 10<sup>k</sup> − 1 делилось на 9n. Подойдёт k = φ(9n).`],
        sol: `Число из k единиц равно ${fr('10<sup>k</sup> − 1', '9')}. Оно делится на n, если 9n <span class="dv">∣</span> 10<sup>k</sup> − 1. Так как n взаимно просто с 10, а 9 тоже, НОД(10, 9n) = 1. По теореме Эйлера при k = φ(9n) получаем 10<sup>k</sup> ≡ 1${md('9n')}, то есть 10<sup>k</sup> − 1 = 9n · t, и число из k единиц равно nt.`,
        rubric: [[2, `Запись числа из единиц как (10<sup>k</sup> − 1)/9`], [3, `Применена теорема Эйлера по модулю 9n с проверкой взаимной простоты`], [2, `Вывод делимости на n`]] },
      { id: 'cong-39', lvl: 5, r: 2240, type: 'num', q: `Найдите остаток от деления числа 2026<sup>2026<sup>2026</sup></sup> на 1000.`, a: ['776'],
        hints: [`1000 = 8 · 125. По модулю 8 ответ 0 — почему?`, `По модулю 125: φ(125) = 100, нужен остаток показателя 2026<sup>2026</sup> по модулю 100. Его тоже собери по модулям 4 и 25.`, `2026 ≡ 26 = 1 + 25${md(125)}, а (1 + 25)<sup>k</sup> ≡ 1 + 25k${md(125)}.`],
        sol: `По модулю 8: 2026 чётное, показатель огромный, поэтому число делится на 8. По модулю 125: основание 2026 ≡ 26, φ(125) = 100, и нужен показатель E = 2026<sup>2026</sup> по модулю 100. По модулю 4: E ≡ 2<sup>2026</sup> ≡ 0; по модулю 25: 2026 ≡ 1, E ≡ 1. Отсюда E ≡ 76${md(100)}. Значит, число ≡ 26<sup>76</sup>${md(125)}. По биному (1 + 25)<sup>76</sup> ≡ 1 + 76 · 25 = 1901 ≡ 26${md(125)} (остальные слагаемые делятся на 25<sup>2</sup>). Остаётся найти x ≡ 0${md(8)}, x ≡ 26${md(125)}: из 26, 151, 276, …, 776 на 8 делится 776.` },
      { id: 'cong-40', lvl: 5, r: 2350, type: 'proof', q: `Пусть p > 2 — простое число. Докажите, что 1<sup>p</sup> + 2<sup>p</sup> + … + (p − 1)<sup>p</sup> делится на p<sup>2</sup>.`,
        hints: [`Сгруппируй слагаемые парами: k<sup>p</sup> + (p − k)<sup>p</sup>.`, `Раскрой (p − k)<sup>p</sup> по биному: все слагаемые, кроме двух последних, делятся на p<sup>2</sup>.`],
        sol: `Слагаемых p − 1 — чётное число, разобьём их на пары k и p − k (k = 1, …, ${fr('p − 1', '2')}). По биному (p − k)<sup>p</sup> = (−k)<sup>p</sup> + p · p · (−k)<sup>p−1</sup> + (слагаемые с p<sup>2</sup> и выше) ≡ −k<sup>p</sup>${md('p<sup>2</sup>')}, потому что p нечётно и второе слагаемое равно p<sup>2</sup>k<sup>p−1</sup>. Значит, k<sup>p</sup> + (p − k)<sup>p</sup> ≡ 0${md('p<sup>2</sup>')}, и сумма всех пар делится на p<sup>2</sup>.`,
        rubric: [[2, `Разбиение на пары k и p − k`], [4, `Доказано (p − k)<sup>p</sup> ≡ −k<sup>p</sup>${md('p<sup>2</sup>')} через бином`], [1, `Вывод`]] }
    ]
  });
})();

// ---- content/cong-deep.js ----
// Глубокий уровень темы «Сравнения по модулю».
// Китайская теорема в конструкциях, обратные элементы и теорема Лагранжа, суммы двух квадратов.
(function () {
  function fr(a, b) { return '<span class="fr"><span>' + a + '</span><span>' + b + '</span></span>'; }
  function sq(x) { return '<span class="sq">√<span>' + x + '</span></span>'; }
  function md(m) { return ' (mod ' + m + ')'; }

  MM.addDeep('cong', {
    lessons: [
      { id: 'cong-l7', title: 'Китайская теорема в конструкциях', mins: 16, html: `
<p>В основном уровне китайская теорема помогала считать. На финале и на международных олимпиадах её главная роль другая — <b>строить</b> числа с нужными свойствами. Если свойство записывается сравнениями по взаимно простым модулям, все их можно выполнить одновременно.</p>
<h3>Решения по модулю — произведение решений по частям</h3>
<p>Если <span class="m">m = m<sub>1</sub>m<sub>2</sub> … m<sub>k</sub></span> с попарно взаимно простыми множителями, то число решений многочленного сравнения <span class="m">f(x) ≡ 0${md('m')}</span> равно произведению чисел решений по модулям <span class="m">m<sub>i</sub></span>: каждому набору решений по частям отвечает ровно одно решение по модулю <span class="m">m</span>.</p>
<div class="ex"><div class="ex-h">Пример 1</div>
<p>Найдите все <span class="m">x</span> от 0 до 64, для которых <span class="m">x<sup>2</sup> + 1</span> делится на 65.</p>
<p><b>Решение.</b> <span class="m">65 = 5 · 13</span>. По модулю 5: <span class="m">x ≡ 2</span> или <span class="m">3</span>. По модулю 13: <span class="m">x ≡ 5</span> или <span class="m">8</span> (<span class="m">25 ≡ 64 ≡ −1</span>). Четыре сочетания дают четыре решения по модулю 65: <span class="m">x = 8, 18, 47, 57</span>. Например, <span class="m">8<sup>2</sup> + 1 = 65</span>, <span class="m">18<sup>2</sup> + 1 = 325 = 5 · 65</span>.</p></div>
<div class="box"><div class="box-h">Сколько корней из единицы</div><ul>
<li>По модулю <span class="m">p<sup>k</sup></span>, <span class="m">p</span> нечётное простое: <span class="m">x<sup>2</sup> ≡ 1</span> только при <span class="m">x ≡ ±1</span>. Действительно, <span class="m">p<sup>k</sup> <span class="dv">∣</span> (x − 1)(x + 1)</span>, а НОД<span class="m">(x − 1, x + 1)</span> делит 2, поэтому <span class="m">p</span> делит лишь один из множителей — и <span class="m">p<sup>k</sup></span> делит его целиком.</li>
<li>По модулю 2 — одно решение, по модулю 4 — два (1 и 3), по модулю 8 — четыре (1, 3, 5, 7).</li>
</ul></div>
<h3>Рецепт конструкции</h3>
<p>Нужно, чтобы числа <span class="m">n + 1, n + 2, …, n + k</span> обладали каждое своим свойством? Назначь каждому числу свой модуль <span class="m">q<sub>i</sub></span> (обычно степень простого или произведение простых), подбери остатки, выражающие свойство, и проследи, чтобы модули были попарно взаимно просты. Китайская теорема даст <span class="m">n</span> — и даже бесконечно много таких <span class="m">n</span>, с шагом <span class="m">q<sub>1</sub>q<sub>2</sub> … q<sub>k</sub></span>.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Слова «докажите, что существует» в теории чисел часто означают китайскую теорему. Главное — выбрать модули так, чтобы они не мешали друг другу: разные простые числа — самый надёжный выбор, ведь простых бесконечно много.</p></div>` },

      { id: 'cong-l8', title: 'Обратные элементы и теорема Лагранжа', mins: 16, html: `
<p>По простому модулю <span class="m">p</span> у каждого ненулевого остатка есть обратный. Отображение <span class="m">k ↦ k<sup>−1</sup></span> переставляет числа <span class="m">1, 2, …, p − 1</span>: разные числа имеют разные обратные. Поэтому сумма любой функции от <span class="m">k<sup>−1</sup></span> по всем <span class="m">k</span> равна сумме той же функции от <span class="m">k</span>.</p>
<div class="ex"><div class="ex-h">Пример 1</div>
<p>В теме «Делимость» ты доказывал, что числитель суммы <span class="m">1 + ${fr('1', '2')} + … + ${fr('1', 'p − 1')}</span> делится на <span class="m">p</span>. С обратными элементами это одна строка: <span class="m">Σ k<sup>−1</sup> ≡ Σ k = ${fr('(p − 1)p', '2')} ≡ 0${md('p')}</span>.</p></div>
<div class="box"><div class="box-h">Теорема Лагранжа</div>
<p>Многочлен степени <span class="m">d</span> с целыми коэффициентами, старший коэффициент которого не делится на простое <span class="m">p</span>, имеет не больше <span class="m">d</span> корней по модулю <span class="m">p</span>.</p></div>
<p><b>Доказательство</b> индукцией по <span class="m">d</span>. Если <span class="m">a</span> — корень, то <span class="m">f(x) − f(a)</span> делится на <span class="m">x − a</span> (разность степеней), то есть <span class="m">f(x) ≡ (x − a)g(x)${md('p')}</span>, где <span class="m">g</span> степени <span class="m">d − 1</span>. Любой другой корень <span class="m">b ≢ a</span> обнуляет <span class="m">g</span>, ведь <span class="m">p</span> простое и <span class="m">p ∤ b − a</span>. По предположению индукции у <span class="m">g</span> не больше <span class="m">d − 1</span> корней.</p>
<p>Важно, что модуль простой: по модулю 8 у <span class="m">x<sup>2</sup> − 1</span> четыре корня.</p>
<h3>Следствия</h3>
<ul>
<li><span class="m">x<sup>2</sup> ≡ a${md('p')}</span> при <span class="m">p ∤ a</span> имеет 0 или 2 решения (<span class="m">x</span> и <span class="m">−x</span>). Поэтому квадратами по модулю нечётного <span class="m">p</span> являются ровно <span class="m">${fr('p − 1', '2')}</span> ненулевых остатков. По модулю 11 это 1, 3, 4, 5, 9.</li>
<li>Если <span class="m">d <span class="dv">∣</span> p − 1</span>, то <span class="m">x<sup>d</sup> ≡ 1</span> имеет не больше <span class="m">d</span> решений. Например, <span class="m">x<sup>3</sup> ≡ 1${md(7)}</span>: это 1, 2, 4.</li>
<li><span class="m">x<sup>p−1</sup> − 1 ≡ (x − 1)(x − 2) … (x − (p − 1))${md('p')}</span>: разность обеих частей — многочлен степени меньше <span class="m">p − 1</span> с <span class="m">p − 1</span> корнями, значит, все его коэффициенты делятся на <span class="m">p</span>. Сравнив свободные члены, снова получаем теорему Вильсона. Проверка при <span class="m">p = 5</span>: <span class="m">(x − 1)(x − 2)(x − 3)(x − 4) = x<sup>4</sup> − 10x<sup>3</sup> + 35x<sup>2</sup> − 50x + 24 ≡ x<sup>4</sup> − 1</span>.</li>
</ul>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Сумма по всем ненулевым остаткам не меняется, если заменить <span class="m">k</span> на <span class="m">k<sup>−1</sup></span> или на <span class="m">ak</span> при <span class="m">p ∤ a</span>. Если от такой замены сумма умножилась на число, отличное от 1, — она равна нулю. А теорема Лагранжа гарантирует, что подходящий множитель найдётся.</p></div>` },

      { id: 'cong-l9', title: 'Суммы двух квадратов', mins: 16, html: `
<p>Какие простые числа представляются в виде <span class="m">a<sup>2</sup> + b<sup>2</sup></span>? <span class="m">2 = 1 + 1</span>, <span class="m">5 = 1 + 4</span>, <span class="m">13 = 4 + 9</span>, <span class="m">17 = 1 + 16</span>, а 3, 7, 11, 19 — нет. Квадраты по модулю 4 дают 0 или 1, поэтому сумма двух квадратов не даёт остаток 3. Оказывается, верно и обратное.</p>
<div class="box"><div class="box-h">Теорема Ферма — Эйлера</div>
<p>Нечётное простое <span class="m">p</span> представляется в виде суммы двух квадратов тогда и только тогда, когда <span class="m">p ≡ 1${md(4)}</span>.</p></div>
<h3>Шаг 1. −1 — квадрат по модулю p = 4k + 1</h3>
<p>Как в задаче про <span class="m">(50!)<sup>2</sup></span> по модулю 101: <span class="m">(p − 1)! ≡ ((${fr('p − 1', '2')})!)<sup>2</sup> · (−1)<sup>(p−1)/2</sup></span>. При <span class="m">p = 4k + 1</span> показатель чётный, и по теореме Вильсона <span class="m">x = (${fr('p − 1', '2')})!</span> удовлетворяет <span class="m">x<sup>2</sup> ≡ −1${md('p')}</span>.</p>
<h3>Шаг 2. Лемма Туэ</h3>
<p>Пусть <span class="m">p ∤ x</span>, <span class="m">s = ⌊${sq('p')}⌋</span>. Рассмотрим числа <span class="m">a − xb</span> при <span class="m">0 ≤ a, b ≤ s</span>. Пар <span class="m">(a, b)</span> всего <span class="m">(s + 1)<sup>2</sup> > p</span>, поэтому две из них дают одинаковый остаток. Их разность — пара <span class="m">(a, b)</span> с <span class="m">|a|, |b| ≤ s < ${sq('p')}</span>, не обе нулевые, и <span class="m">a ≡ xb${md('p')}</span>. Ни <span class="m">a</span>, ни <span class="m">b</span> не равны нулю (иначе и второе делилось бы на <span class="m">p</span>).</p>
<h3>Шаг 3. Собираем</h3>
<p>Возьмём <span class="m">x</span> с <span class="m">x<sup>2</sup> ≡ −1</span> и пару из леммы Туэ: <span class="m">a<sup>2</sup> ≡ x<sup>2</sup>b<sup>2</sup> ≡ −b<sup>2</sup></span>, то есть <span class="m">p <span class="dv">∣</span> a<sup>2</sup> + b<sup>2</sup></span>. А <span class="m">0 < a<sup>2</sup> + b<sup>2</sup> < 2p</span>, значит, <span class="m">a<sup>2</sup> + b<sup>2</sup> = p</span>.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p><span class="m">p = 13</span>, <span class="m">x = 5</span> (<span class="m">25 ≡ −1</span>), <span class="m">s = 3</span>. При <span class="m">b = 2</span>: <span class="m">xb = 10 ≡ −3</span>, то есть <span class="m">a = 3</span>. И действительно, <span class="m">3<sup>2</sup> + 2<sup>2</sup> = 13</span>.</p></div>
<h3>Произвольные числа</h3>
<p>Тождество <span class="m">(a<sup>2</sup> + b<sup>2</sup>)(c<sup>2</sup> + d<sup>2</sup>) = (ac − bd)<sup>2</sup> + (ad + bc)<sup>2</sup></span> (оно было в теме «Выражения и тождества») показывает, что произведение сумм двух квадратов — снова сумма двух квадратов. Например, <span class="m">65 = 5 · 13 = 1<sup>2</sup> + 8<sup>2</sup> = 4<sup>2</sup> + 7<sup>2</sup></span>. А простое <span class="m">p = 4k + 3</span>, делящее <span class="m">a<sup>2</sup> + b<sup>2</sup></span>, делит и <span class="m">a</span>, и <span class="m">b</span> (задача основного уровня), поэтому входит в <span class="m">a<sup>2</sup> + b<sup>2</sup></span> в чётной степени.</p>
<div class="box"><div class="box-h">Итог</div>
<p>Натуральное <span class="m">n</span> — сумма двух квадратов целых чисел тогда и только тогда, когда каждое простое вида <span class="m">4k + 3</span> входит в разложение <span class="m">n</span> в чётной степени. Более того, число представлений <span class="m">n = a<sup>2</sup> + b<sup>2</sup></span> в целых числах (с учётом знаков и порядка) равно <span class="m">4(d<sub>1</sub> − d<sub>3</sub>)</span>, где <span class="m">d<sub>1</sub></span> и <span class="m">d<sub>3</sub></span> — количества делителей <span class="m">n</span> вида <span class="m">4k + 1</span> и <span class="m">4k + 3</span>.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Видишь <span class="m">a<sup>2</sup> + b<sup>2</sup></span>, <span class="m">n<sup>2</sup> + 1</span> или <span class="m">x<sup>2</sup> + y<sup>2</sup> = …</span> — сразу смотри на простые делители вида <span class="m">4k + 3</span>: они делят оба слагаемых. Это доказывает невозможность многих уравнений в одну строку.</p></div>` }
    ],

    problems: [
      // ── Уровень 4 · Финал ──
      { id: 'cong-41', lvl: 4, r: 1960, type: 'num', q: `Сколько решений имеет сравнение x<sup>2</sup> ≡ 1${md(1000)} среди чисел 0, 1, 2, …, 999?`, a: ['8'],
        hints: [`1000 = 8 · 125. Посчитай решения по каждому модулю отдельно.`, `По модулю 8 подходят все нечётные остатки, по модулю 125 — только ±1.`],
        sol: `По китайской теореме число решений равно произведению чисел решений по модулям 8 и 125. По модулю 8 квадрат любого нечётного числа ≡ 1: решения 1, 3, 5, 7 — четыре. По модулю 125: 125 <span class="dv">∣</span> (x − 1)(x + 1), а НОД(x − 1, x + 1) делит 2, поэтому 5 делит лишь один множитель, и 125 делит его целиком: x ≡ ±1 — два решения. Всего 4 · 2 = 8.` },
      { id: 'cong-42', lvl: 4, r: 1970, type: 'num', q: `Сколько решений имеет сравнение x<sup>3</sup> ≡ x${md(105)} среди чисел 0, 1, 2, …, 104?`, a: ['27'],
        hints: [`105 = 3 · 5 · 7. По простому модулю x<sup>3</sup> − x = x(x − 1)(x + 1).`],
        sol: `По каждому из простых модулей 3, 5, 7 сравнение x(x − 1)(x + 1) ≡ 0 имеет ровно три решения: 0, 1 и −1 (они различны, так как p ≥ 3, а простое делит произведение, только если делит множитель). По китайской теореме решений 3 · 3 · 3 = 27.` },
      { id: 'cong-43', lvl: 4, r: 1980, type: 'num', q: `Число 101 — простое. Сколько решений имеет сравнение x<sup>4</sup> ≡ 1${md(101)} среди чисел 1, 2, …, 100?`, a: ['4'],
        hints: [`x<sup>4</sup> − 1 = (x − 1)(x + 1)(x<sup>2</sup> + 1). По теореме Лагранжа решений не больше 4.`, `Есть ли решения у x<sup>2</sup> ≡ −1${md(101)}? Посмотри на 10<sup>2</sup>.`],
        sol: `x<sup>4</sup> − 1 = (x − 1)(x + 1)(x<sup>2</sup> + 1). Сравнение x<sup>2</sup> ≡ 1 даёт x ≡ ±1, то есть 1 и 100. Сравнение x<sup>2</sup> ≡ −1 тоже разрешимо: 10<sup>2</sup> = 100 ≡ −1, решения 10 и 91. Это четыре различных решения, а по теореме Лагранжа у многочлена четвёртой степени по простому модулю их не больше четырёх. Ответ: 4.` },
      { id: 'cong-44', lvl: 4, r: 1990, type: 'num', q: `Сколько натуральных чисел от 1 до 100 можно представить в виде a<sup>2</sup> + b<sup>2</sup>, где a и b — целые числа?`, a: ['43'],
        hints: [`Нуль разрешён: 4 = 2<sup>2</sup> + 0<sup>2</sup>.`, `Критерий из урока: каждое простое вида 4k + 3 должно входить в число в чётной степени.`, `Можно и перебрать все пары 0 ≤ a ≤ b ≤ 10.`],
        sol: `По критерию (или прямым перебором пар 0 ≤ a ≤ b ≤ 10) подходят числа 1, 2, 4, 5, 8, 9, 10, 13, 16, 17, 18, 20, 25, 26, 29, 32, 34, 36, 37, 40, 41, 45, 49, 50, 52, 53, 58, 61, 64, 65, 68, 72, 73, 74, 80, 81, 82, 85, 89, 90, 97, 98, 100. Их 43. Например, 45 = 3<sup>2</sup> · 5 подходит (тройка в чётной степени), а 21 = 3 · 7 и 63 = 3<sup>2</sup> · 7 — нет.` },
      { id: 'cong-45', lvl: 4, r: 2000, type: 'proof', q: `Докажите, что существуют 2026 подряд идущих натуральных чисел, каждое из которых делится на квадрат некоторого натурального числа, большего 1.`,
        hints: [`Возьми 2026 различных простых p<sub>1</sub>, …, p<sub>2026</sub> и потребуй n + i ≡ 0${md('p<sub>i</sub><sup>2</sup>')}.`, `Модули p<sub>1</sub><sup>2</sup>, …, p<sub>2026</sub><sup>2</sup> попарно взаимно просты.`],
        sol: `Возьмём 2026 различных простых чисел p<sub>1</sub>, p<sub>2</sub>, …, p<sub>2026</sub> (простых бесконечно много). Модули p<sub>1</sub><sup>2</sup>, …, p<sub>2026</sub><sup>2</sup> попарно взаимно просты, поэтому по китайской теореме найдётся натуральное n, для которого n ≡ −i${md('p<sub>i</sub><sup>2</sup>')} при всех i = 1, …, 2026. Тогда числа n + 1, n + 2, …, n + 2026 делятся на p<sub>1</sub><sup>2</sup>, p<sub>2</sub><sup>2</sup>, …, p<sub>2026</sub><sup>2</sup> соответственно.`,
        rubric: [[2, `Выбраны различные простые и их квадраты как модули`], [2, `Отмечено, что модули попарно взаимно просты`], [2, `Применена китайская теорема: n ≡ −i${md('p<sub>i</sub><sup>2</sup>')}`], [1, `Вывод`]] },
      { id: 'cong-46', lvl: 4, r: 2010, type: 'proof', q: `Пусть p > 3 — простое число и <span class="nw">1 + ${fr('1', '2<sup>2</sup>')} + ${fr('1', '3<sup>2</sup>')} + … + ${fr('1', '(p − 1)<sup>2</sup>')} = ${fr('m', 'n')}</span> — несократимая дробь. Докажите, что m делится на p.`,
        hints: [`Общий знаменатель ((p − 1)!)<sup>2</sup> не делится на p. Достаточно доказать, что числитель N делится на p.`, `По модулю p число (p − 1)!/k ≡ (p − 1)! · k<sup>−1</sup>, а k ↦ k<sup>−1</sup> — перестановка остатков.`, `1<sup>2</sup> + 2<sup>2</sup> + … + (p − 1)<sup>2</sup> = (p − 1)p(2p − 1)/6.`],
        sol: `Приведём к общему знаменателю D = ((p − 1)!)<sup>2</sup>, который не делится на p. Числитель N = Σ ((p − 1)!/k)<sup>2</sup>. По модулю p имеем (p − 1)!/k ≡ (p − 1)! · k<sup>−1</sup>, поэтому N ≡ ((p − 1)!)<sup>2</sup> · Σ (k<sup>−1</sup>)<sup>2</sup>. Когда k пробегает 1, …, p − 1, обратный k<sup>−1</sup> пробегает те же остатки, так что Σ (k<sup>−1</sup>)<sup>2</sup> ≡ Σ k<sup>2</sup> = ${fr('(p − 1)p(2p − 1)', '6')}. При p > 3 число 6 взаимно просто с p, и сумма делится на p. Итак, p <span class="dv">∣</span> N. Дробь m/n получается из N/D сокращением на общий делитель g чисел N и D; g делит D, поэтому p ∤ g, и p <span class="dv">∣</span> m.`,
        rubric: [[2, `Сведение к делимости числителя на p (знаменатель на p не делится)`], [3, `Замена k на k<sup>−1</sup> — перестановка, сумма обратных квадратов ≡ сумме квадратов`], [2, `Сумма квадратов делится на p при p > 3, вывод для m`]] },
      { id: 'cong-47', lvl: 4, r: 2030, type: 'num', q: `Найдите наибольшее шестизначное число N, у которого квадрат оканчивается теми же шестью цифрами, что и само N, то есть N<sup>2</sup> ≡ N${md('10<sup>6</sup>')}.`, a: ['890625'],
        hints: [`N<sup>2</sup> ≡ N означает N(N − 1) ≡ 0${md('2<sup>6</sup> · 5<sup>6</sup>')}.`, `N и N − 1 взаимно просты, поэтому 2<sup>6</sup> делит одно из них целиком, и 5<sup>6</sup> — тоже.`, `Шестизначные ответы дают случаи N ≡ 0${md('5<sup>6</sup>')}, N ≡ 1${md('2<sup>6</sup>')} и наоборот.`],
        sol: `10<sup>6</sup> = 2<sup>6</sup> · 5<sup>6</sup> = 64 · 15625. Так как N и N − 1 взаимно просты, 2<sup>6</sup> делит одно из них, и 5<sup>6</sup> — тоже одно из них. Если это одно и то же число, то N ≡ 0 или N ≡ 1${md('10<sup>6</sup>')} — не шестизначное. Случай N ≡ 0${md(15625)}, N ≡ 1${md(64)}: N = 15625k, и 15625 ≡ 9${md(64)}, обратный к 9 — это 57 (9 · 57 = 513 = 8 · 64 + 1), поэтому N = 15625 · 57 = 890625. Второй случай даёт N = 10<sup>6</sup> + 1 − 890625 = 109376. Наибольшее — 890625.` },
      { id: 'cong-48', lvl: 4, r: 2050, type: 'proof', q: `Докажите, что простых чисел вида 4k + 1 бесконечно много.`,
        hints: [`Пусть p<sub>1</sub>, …, p<sub>s</sub> — все такие простые. Рассмотри N = (2p<sub>1</sub>p<sub>2</sub>…p<sub>s</sub>)<sup>2</sup> + 1.`, `Любой простой делитель N нечётен и не может давать остаток 3 при делении на 4.`],
        sol: `Пусть простых вида 4k + 1 конечное число: p<sub>1</sub>, …, p<sub>s</sub>. Рассмотрим N = (2p<sub>1</sub>…p<sub>s</sub>)<sup>2</sup> + 1 > 1 и его простой делитель q. N нечётно, поэтому q ≠ 2. При x = 2p<sub>1</sub>…p<sub>s</sub> получаем x<sup>2</sup> ≡ −1${md('q')}, а для простого вида 4k + 3 это невозможно (по теореме Ферма, как доказано в основном уровне). Значит, q = 4k + 1, то есть q — одно из p<sub>i</sub>. Но тогда q делит и (2p<sub>1</sub>…p<sub>s</sub>)<sup>2</sup>, и N, а значит, делит 1 — противоречие.`,
        rubric: [[2, `Построено число N = (2p<sub>1</sub>…p<sub>s</sub>)<sup>2</sup> + 1`], [3, `Доказано, что простой делитель N имеет вид 4k + 1`], [2, `Получено противоречие`]] },

      // ── Уровень 5 · Международный ──
      { id: 'cong-49', lvl: 5, r: 2100, type: 'num', q: `Сколькими способами число 5525 можно записать в виде a<sup>2</sup> + b<sup>2</sup>, где a и b — натуральные числа и a ≤ b?`, a: ['6'],
        hints: [`5525 = 5<sup>2</sup> · 13 · 17, и все три простых дают остаток 1 при делении на 4.`, `Число представлений в целых числах — 4(d<sub>1</sub> − d<sub>3</sub>). Посчитай делители вида 4k + 1 и 4k + 3.`, `Можно и перебрать: b от 53 до 74, проверяя, квадрат ли 5525 − b<sup>2</sup>.`],
        sol: `У 5525 = 5<sup>2</sup> · 13 · 17 всего 3 · 2 · 2 = 12 делителей, и все они вида 4k + 1 (простые множители такого вида). Поэтому представлений в целых числах 4 · 12 = 48. Нулевых среди них нет (5525 не квадрат), так что в натуральных числах с учётом порядка их 48 : 4 = 12, а без учёта порядка — 6 (a = b невозможно: 5525/2 — не квадрат). Вот они: 7<sup>2</sup> + 74<sup>2</sup>, 14<sup>2</sup> + 73<sup>2</sup>, 22<sup>2</sup> + 71<sup>2</sup>, 25<sup>2</sup> + 70<sup>2</sup>, 41<sup>2</sup> + 62<sup>2</sup>, 50<sup>2</sup> + 55<sup>2</sup>.` },
      { id: 'cong-50', lvl: 5, r: 2180, type: 'proof', q: `Докажите, что ни при каких натуральных m и n число 4mn − m − n не является квадратом целого числа.`,
        hints: [`Пусть 4mn − m − n = k<sup>2</sup>. Умножь на 4 и прибавь 1.`, `(4m − 1)(4n − 1) = (2k)<sup>2</sup> + 1.`, `У числа 4m − 1 есть простой делитель вида 4t + 3.`],
        sol: `Пусть 4mn − m − n = k<sup>2</sup>. Тогда 16mn − 4m − 4n + 1 = 4k<sup>2</sup> + 1, то есть (4m − 1)(4n − 1) = (2k)<sup>2</sup> + 1. Число 4m − 1 ≥ 3 даёт остаток 3 при делении на 4, поэтому у него есть простой делитель q вида 4t + 3: произведение чисел вида 4t + 1 снова имеет такой вид. Тогда q <span class="dv">∣</span> (2k)<sup>2</sup> + 1, то есть (2k)<sup>2</sup> ≡ −1${md('q')}, что невозможно для простого q = 4t + 3. Противоречие.`,
        rubric: [[2, `Преобразование к (4m − 1)(4n − 1) = (2k)<sup>2</sup> + 1`], [2, `У 4m − 1 есть простой делитель вида 4t + 3`], [3, `Противоречие: −1 не квадрат по модулю такого простого`]] },
      { id: 'cong-51', lvl: 5, r: 2260, type: 'num', q: `Сколько существует пар (x, y) остатков по модулю 101 (0 ≤ x, y ≤ 100), для которых x<sup>2</sup> + y<sup>2</sup> ≡ 1${md(101)}?`, a: ['100'],
        hints: [`По модулю 101 есть i с i<sup>2</sup> ≡ −1 (например, i = 10). Тогда x<sup>2</sup> + y<sup>2</sup> ≡ (x + iy)(x − iy).`, `Замена u = x + iy, v = x − iy обратима. Условие превращается в uv ≡ 1.`],
        sol: `Пусть i = 10, i<sup>2</sup> = 100 ≡ −1. Тогда x<sup>2</sup> + y<sup>2</sup> ≡ (x + iy)(x − iy). Отображение (x, y) ↦ (u, v) = (x + iy, x − iy) обратимо: x ≡ (u + v) · 2<sup>−1</sup>, y ≡ (u − v) · (2i)<sup>−1</sup> — делить можно, потому что 2 и i обратимы по модулю 101. Значит, пар (x, y) столько же, сколько пар (u, v) с uv ≡ 1: для каждого из 100 ненулевых u ровно одно v = u<sup>−1</sup>. Ответ: 100.` },
      { id: 'cong-52', lvl: 5, r: 2320, type: 'proof', q: `Пусть p — простое число и k — натуральное. Докажите, что 1<sup>k</sup> + 2<sup>k</sup> + … + (p − 1)<sup>k</sup> ≡ 0${md('p')}, если p − 1 не делит k, и ≡ −1${md('p')}, если p − 1 делит k.`,
        hints: [`Случай p − 1 <span class="dv">∣</span> k — теорема Ферма.`, `Иначе пусть r — остаток k при делении на p − 1, 0 < r < p − 1. По теореме Лагранжа x<sup>r</sup> ≡ 1 имеет меньше p − 1 решений.`, `Возьми a с a<sup>k</sup> ≢ 1. Умножение на a переставляет остатки 1, …, p − 1.`],
        sol: `Если p − 1 <span class="dv">∣</span> k, то по теореме Ферма каждое слагаемое ≡ 1, и сумма ≡ p − 1 ≡ −1. Пусть p − 1 ∤ k и r — остаток k при делении на p − 1, 0 < r < p − 1. Для x, не делящегося на p, x<sup>k</sup> ≡ x<sup>r</sup> (теорема Ферма). По теореме Лагранжа у x<sup>r</sup> ≡ 1 не больше r < p − 1 решений, поэтому найдётся a, 1 ≤ a ≤ p − 1, с a<sup>k</sup> ≢ 1. Числа a · 1, a · 2, …, a · (p − 1) дают все ненулевые остатки в другом порядке, поэтому S = Σ j<sup>k</sup> ≡ Σ (aj)<sup>k</sup> = a<sup>k</sup>S. Значит, (a<sup>k</sup> − 1)S ≡ 0, и так как a<sup>k</sup> − 1 не делится на p, S ≡ 0${md('p')}.`,
        rubric: [[1, `Разобран случай p − 1 <span class="dv">∣</span> k`], [3, `Доказано существование a с a<sup>k</sup> ≢ 1 (сведение к r и теорема Лагранжа)`], [3, `Перестановка остатков умножением на a, S ≡ a<sup>k</sup>S, вывод`]] },
      { id: 'cong-53', lvl: 5, r: 2380, type: 'proof', q: `Докажите, что для любого натурального n существуют n подряд идущих натуральных чисел, ни одно из которых не является степенью простого числа с натуральным показателем. (Международная олимпиада, 1989)`,
        hints: [`Число не является степенью простого, если делится на два различных простых.`, `Возьми 2n различных простых p<sub>1</sub>, q<sub>1</sub>, …, p<sub>n</sub>, q<sub>n</sub> и потребуй, чтобы x + i делилось на p<sub>i</sub>q<sub>i</sub>.`],
        sol: `Возьмём 2n различных простых p<sub>1</sub>, q<sub>1</sub>, p<sub>2</sub>, q<sub>2</sub>, …, p<sub>n</sub>, q<sub>n</sub>. Числа p<sub>1</sub>q<sub>1</sub>, …, p<sub>n</sub>q<sub>n</sub> попарно взаимно просты, поэтому по китайской теореме найдётся натуральное x, для которого x + i ≡ 0${md('p<sub>i</sub>q<sub>i</sub>')} при всех i = 1, …, n. Каждое из чисел x + 1, …, x + n делится на два различных простых p<sub>i</sub> и q<sub>i</sub>, а у степени простого только один простой делитель. Значит, ни одно из этих чисел не является степенью простого.`,
        rubric: [[3, `Идея: у каждого числа два различных простых делителя`], [3, `Построение по китайской теореме с попарно взаимно простыми модулями p<sub>i</sub>q<sub>i</sub>`], [1, `Вывод`]] },
      { id: 'cong-54', lvl: 5, r: 2440, type: 'proof', q: `Пусть p — простое число и p = a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup> + d<sup>2</sup>, где a, b, c, d — натуральные. Докажите, что {a, b} = {c, d}, то есть представление простого числа в виде суммы двух квадратов единственно.`,
        hints: [`p<sup>2</sup> = (a<sup>2</sup> + b<sup>2</sup>)(c<sup>2</sup> + d<sup>2</sup>) = (ac + bd)<sup>2</sup> + (ad − bc)<sup>2</sup> = (ac − bd)<sup>2</sup> + (ad + bc)<sup>2</sup>.`, `(ac + bd)(ad + bc) = p(ab + cd), поэтому p делит один из множителей.`, `Если p <span class="dv">∣</span> ac + bd, то ac + bd = p и ad − bc = 0.`],
        sol: `Раскроем скобки: (ac + bd)(ad + bc) = a<sup>2</sup>cd + abc<sup>2</sup> + abd<sup>2</sup> + b<sup>2</sup>cd = cd(a<sup>2</sup> + b<sup>2</sup>) + ab(c<sup>2</sup> + d<sup>2</sup>) = p(ab + cd). Значит, p делит ac + bd или ad + bc.<br>Пусть p <span class="dv">∣</span> ac + bd. По тождеству p<sup>2</sup> = (ac + bd)<sup>2</sup> + (ad − bc)<sup>2</sup>, поэтому 0 < ac + bd ≤ p, то есть ac + bd = p, и тогда ad − bc = 0, ${fr('a', 'b')} = ${fr('c', 'd')}. Общий делитель a и b в квадрате делит p, поэтому НОД(a, b) = 1, и так же НОД(c, d) = 1. Равные несократимые дроби совпадают: a = c, b = d.<br>Если p <span class="dv">∣</span> ad + bc, то так же из p<sup>2</sup> = (ac − bd)<sup>2</sup> + (ad + bc)<sup>2</sup> получаем ad + bc = p, ac = bd, ${fr('a', 'b')} = ${fr('d', 'c')}, и a = d, b = c.`,
        rubric: [[2, `Два представления p<sup>2</sup> через тождество для сумм квадратов`], [2, `(ac + bd)(ad + bc) = p(ab + cd), p делит один из множителей`], [2, `Из ac + bd = p следует ad = bc (и аналогично во втором случае)`], [1, `Взаимная простота и вывод`]] },
      { id: 'cong-55', lvl: 5, r: 2490, type: 'proof', q: `Найдите все простые p, для которых (p − 1)! + 1 является натуральной степенью числа p, и докажите, что других нет.`,
        hints: [`Проверь p = 2, 3, 5.`, `Пусть p ≥ 7 и (p − 1)! + 1 = p<sup>k</sup>. Тогда (p − 1)! = p<sup>k</sup> − 1 = (p − 1)(p<sup>k−1</sup> + … + p + 1).`, `Сократи на p − 1: (p − 2)! = p<sup>k−1</sup> + … + 1 ≡ k${md('p − 1')}. Докажи, что p − 1 делит (p − 2)!.`],
        sol: `p = 2: 1! + 1 = 2; p = 3: 2! + 1 = 3; p = 5: 4! + 1 = 25 = 5<sup>2</sup> — подходят. Пусть p ≥ 7 и (p − 1)! + 1 = p<sup>k</sup>. Тогда (p − 1)! = p<sup>k</sup> − 1 = (p − 1)(p<sup>k−1</sup> + … + p + 1), откуда (p − 2)! = p<sup>k−1</sup> + … + p + 1. Так как p ≡ 1${md('p − 1')}, правая часть ≡ k${md('p − 1')}. С другой стороны, p − 1 = 2 · ${fr('p − 1', '2')}, и при p ≥ 7 множители 2 и ${fr('p − 1', '2')} различны и не больше p − 2, поэтому оба входят в (p − 2)!, и p − 1 <span class="dv">∣</span> (p − 2)!. Значит, p − 1 <span class="dv">∣</span> k и k ≥ p − 1. Но тогда p<sup>k</sup> ≥ p<sup>p−1</sup> > (p − 1)<sup>p−1</sup> ≥ (p − 1)! + 1 — противоречие. Ответ: p = 2, 3, 5. (Это теорема Лиувилля.)`,
        rubric: [[1, `Проверены p = 2, 3, 5`], [2, `(p − 2)! = p<sup>k−1</sup> + … + 1 ≡ k${md('p − 1')}`], [2, `p − 1 делит (p − 2)! при p ≥ 7`], [2, `Оценка k ≥ p − 1 и противоречие`]] }
    ]
  });
})();

